import { documentedEvaluation } from '../helpers.js';
import { normalizeEmployee } from '../../server/pay.js';

// Independent, hand-calculable reference. Annual and hourly rankings are reversed.
// Men: 8 x (60000 + 6000) / 2000 h. Women: 4 x (30000 + 3000) / 500 h,
// plus 4 x 30000 / 500 h. No real persons, no real employer.
export const referenceRows = Array.from({ length: 16 }, (_, i) => normalizeEmployee({
  internal_id: `synthetic-${i}`, gender: i < 8 ? 'M' : 'F', job_title: 'Reference role', worker_category: 'Reference category',
  base_annual: i < 8 ? 60000 : 30000, bonuses_annual: i < 8 ? 6000 : i < 12 ? 3000 : 0,
  paid_hours_annual: i < 8 ? 2000 : 500, hours_per_week: i < 8 ? 40 : 10,
}, 'synthetic-reference', 'synthetic-secret-not-production'));

export const referenceWorkflow = {
  snapshotId: 'synthetic-reference-2026',
  profile: { legalName: 'Synthetic reference employer', headcount: 16, payrollComplete: true },
  jobEvaluation: documentedEvaluation(['Reference category']),
  classification: { 'Reference category': { skills: 'Synthetic skills', effort: 'Synthetic effort', responsibility: 'Synthetic responsibility', conditions: 'Synthetic conditions' } },
  criteriaAgreement: { status: 'agreed', note: 'Synthetic agreement' },
  reviews: { 'Reference category': { explanation: 'Synthetic example: pay differences require correction.', justified: false, remedied: false, action: 'Synthetic adjustment plan', owner: 'Synthetic HR', due: '2027-05-01' } },
  approval: { manager: 'Synthetic management', representatives: 'Synthetic consultation', confirmed: true, consulted: true },
  assessment: { jointReviewConfirmed: true, previousMeasures: 'First synthetic assessment: no earlier measures to evaluate.',
    leaveReturn: {}, leaveOutcomes: { 'Reference category': { applicable: true, note: 'Synthetic eligible returners only.', men: { eligible: 8, benefited: 4 }, women: { eligible: 8, benefited: 6 } } } },
  reportingDate: '',
};
export const referenceSnapshot = (audience = 'authority') => ({ id: 'synthetic-reference-2026', reporting_year: 2026, rows: structuredClone(referenceRows), workflow: structuredClone(referenceWorkflow), audience, prepared: false });

